local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")
local LocalPlayer = Players.LocalPlayer

local noclipActive = false
local originalCollisions = {}
local toggleButton = LMG2L["TextButton_5"]
local statusDisplay = LMG2L["_8"]

local connection
connection = RunService.Stepped:Connect(function()
    if noclipActive and LocalPlayer.Character then
        for _, part in ipairs(LocalPlayer.Character:GetDescendants()) do
            if part:IsA("BasePart") then
                if originalCollisions[part] == nil then
                    originalCollisions[part] = part.CanCollide
                end
                part.CanCollide = false
            end
        end
    end
end)

local function restoreCollisions()
    if LocalPlayer.Character then
        for part, wasCollidable in pairs(originalCollisions) do
            if part and part:IsDescendantOf(LocalPlayer.Character) then
                part.CanCollide = wasCollidable
            end
        end
    end
    table.clear(originalCollisions)
end

LocalPlayer.CharacterAdded:Connect(function()
    table.clear(originalCollisions)
    if not noclipActive then
        statusDisplay.Text = "status:off"
        statusDisplay.TextColor3 = Color3.fromRGB(150, 0, 0)
    end
end)

local function checkIsOverButton(inputPosition)
    local absPos = toggleButton.AbsolutePosition
    local absSize = toggleButton.AbsoluteSize
    return inputPosition.X >= absPos.X and inputPosition.X <= (absPos.X + absSize.X)
       and inputPosition.Y >= absPos.Y and inputPosition.Y <= (absPos.Y + absSize.Y)
end

UserInputService.InputBegan:Connect(function(input, gameProcessed)
    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
        if checkIsOverButton(input.Position) then
            noclipActive = not noclipActive

            if noclipActive then
                statusDisplay.Text = "status:on"
                statusDisplay.TextColor3 = Color3.fromRGB(20, 150, 0)
            else
                statusDisplay.Text = "status:off"
                statusDisplay.TextColor3 = Color3.fromRGB(150, 0, 0)
                restoreCollisions()
            end
        end
    end
end)

return LMG2L["ScreenGui_1"], require;
